const insert=(target,html)=>{const template=document.createElement('template');template.innerHTML=html;$(target).appendChild(template.content);};
const button=(text,action)=>{const b=node('button',text);b.type='button';b.className='secondary-button';b.addEventListener('click',action);return b;};
function icon(name){const source=window.TramontoIcons?.[name];if(!source)return null;const svg=document.importNode(new DOMParser().parseFromString(source,'image/svg+xml').documentElement,true);svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');svg.setAttribute('class','ui-icon');return svg;}
const notebookDrawer=node('details');notebookDrawer.id='notebookDrawer';notebookDrawer.appendChild(node('summary','Quaderni e pagine'));const sidebar=document.querySelector('.notebooks-panel');while(sidebar.firstChild)notebookDrawer.appendChild(sidebar.firstChild);sidebar.appendChild(notebookDrawer);const mobileNotes=matchMedia('(max-width:760px)');notebookDrawer.open=!mobileNotes.matches;mobileNotes.addEventListener('change',()=>{notebookDrawer.open=!mobileNotes.matches;});
let restoring=false,positionTimer=0,paginationTimer=0,paginating=false,job=null,pollTimer=0,netMode='select',netType='pc',netSelected=null,netStart=null,netDrag=null,netHistory=[],networkSelection=null,circuitSelection=null;
function storePosition(keepalive=false){if(!doc||restoring||!csrf)return;fetch('/api/tramonto/workspace',{method:'POST',credentials:'same-origin',keepalive,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({notebook_id:doc.notebook_id,note_id:doc.id,scroll_y:Math.round(window.scrollY)})}).catch(()=>{});}
function restorePosition(y){restoring=true;requestAnimationFrame(()=>requestAnimationFrame(()=>{window.scrollTo(0,Number(y)||0);setTimeout(()=>{restoring=false;storePosition();},400);}));}
window.addEventListener('scroll',()=>{clearTimeout(positionTimer);positionTimer=setTimeout(storePosition,700);},{passive:true});
