function fitPage(){const sheet=$('a4Sheet'),frame=$('a4Frame');if(!sheet||!frame||!frame.clientWidth)return;const zoom=$('pageZoom')?.value||'fit',scale=zoom==='fit'?Math.min(1,frame.clientWidth/794):Number(zoom)/100;frame.classList.toggle('zoomed',zoom!=='fit');sheet.style.transform='scale('+scale+')';frame.style.height=(1123*scale)+'px';
 const editor=$('richEditor'),style=getComputedStyle(editor),probe=node('div'),marker=node('span');probe.style.cssText='position:absolute;left:-10000px;top:0;white-space:nowrap;padding:0;margin:0;line-height:28px;font:'+style.font;probe.style.lineHeight='28px';marker.style.cssText='display:inline-block;width:0;height:0;padding:0;margin:0';probe.append('Abg',marker);document.body.appendChild(probe);const baseline=marker.getBoundingClientRect().top-probe.getBoundingClientRect().top;probe.remove();editor.style.setProperty('--rule-offset',(baseline-28)+'px');}
