function openNote(){ clearCircuitImport();resetSimulationForNote();resetImage();networkSelection?.clear();circuitSelection?.clear();if(mobileNotes.matches)notebookDrawer.open=false;$('bookCollection').hidden=true;$('pageNumber').textContent='Pagina '+doc.page_number+' · A4';$('sheetNumber').textContent=doc.page_number;netSelected=null;netStart=null;netHistory=[];renderNetwork();fitPage();storePosition();$('pageHint').textContent=$('richEditor').scrollHeight>$('richEditor').clientHeight+2?'Questa pagina contiene testo lungo: usa «Distribuisci testo su A4» per numerarlo su più pagine.':'Formato A4 · il testo che supera la pagina continua su una nuova pagina.';}
async function navigatePage(direction){if(!doc||!await saveDoc())return;const list=(await api('/api/tramonto/notes?notebook='+bookId)).notes,index=list.findIndex(n=>n.id===doc.id),target=list[index+direction];if(target)await windowOpen(target.id);else if(direction>0)await newNote();}
