async function collection(){if(!await saveDoc())return;await loadBooks();$('noteEditor').hidden=true;$('emptyNote').hidden=true;$('bookCollection').hidden=false;renderCollection();}
function renderCollection(){const grid=$('collectionGrid'),search=$('collectionSearch').value.toLocaleLowerCase();grid.replaceChildren();for(const book of books.filter(b=>b.title.toLocaleLowerCase().includes(search))){const card=button('',async()=>{bookId=book.id;$('bookCollection').hidden=true;doc=null;await loadBooks();await loadNotes();if(notes.length)await openNoteLexical(notes[0].id,true);else{$('emptyNote').hidden=false;}});card.className='notebook-cover cover-'+(book.id%5);const cover=node('span','◒');cover.className='cover-symbol';card.append(cover,node('strong',book.title),node('small',book.note_count+' pagine · Apri quaderno →'));grid.appendChild(card);}if(!grid.children.length)grid.appendChild(node('p','Nessun quaderno con questo nome.'));}
