insert('pane-math','<div class="math-section"><h3>Dal calcolo all’idea.</h3><p class="tool-note">Radianti · seno, coseno, tangente, inverse e iperboliche, radici, logaritmi, esponenziali, min e max.</p><div class="calculus-tools"><label>f(x)<input id="calcExpression" value="x^2" maxlength="250"></label><label>x / estremo a<input id="calcA" type="number" value="0" step="any"></label><label>Estremo b<input id="calcB" type="number" value="1" step="any"></label></div><div class="tool-actions"><button id="calculateValue" class="secondary-button">Valore f(a)</button><button id="calculateDerivative" class="secondary-button">Derivata simbolica</button><button id="calculateIntegral" class="secondary-button">Integrale numerico</button><button id="calculateRoot" class="secondary-button">Zero nell’intervallo</button></div><p id="calculusResult" role="status" class="tool-message"></p></div>');
const calculus=action=>{try{const expression=$('calcExpression').value,fn=expressionFunction(expression),a=Number($('calcA').value),b=Number($('calcB').value);if(!Number.isFinite(a)||!Number.isFinite(b)||Math.abs(a)>10000||Math.abs(b)>10000)throw Error('Estremi finiti tra −10000 e 10000.');let result;
 if(action==='value')result='f('+a+') = '+fn(a);
 if(action==='derivative')result="f′(x) = "+math.derivative(expression,'x').toString();
 if(action==='integral'){if(a>=b)throw Error('Scegli a < b.');const n=1000,h=(b-a)/n;let sum=fn(a)+fn(b);for(let i=1;i<n;i++)sum+=(i%2?4:2)*fn(a+i*h);if(!Number.isFinite(sum))throw Error('Campioni non finiti: controlla dominio e discontinuità.');result='∫ da '+a+' a '+b+' ≈ '+(sum*h/3).toPrecision(10)+' · Simpson, 1000 intervalli; stima numerica.';}
 if(action==='root'){let lo=a,hi=b,flo=fn(lo),fhi=fn(hi);if(lo>=hi||!Number.isFinite(flo)||!Number.isFinite(fhi)||flo*fhi>0)throw Error('Serve un intervallo crescente con valori finiti e segno diverso.');for(let i=0;i<50;i++){const mid=(lo+hi)/2,fm=fn(mid);if(!Number.isFinite(fm))throw Error('Discontinuità rilevata nell’intervallo.');if(flo*fm<=0){hi=mid;fhi=fm;}else{lo=mid;flo=fm;}}const value=(lo+hi)/2;if(Math.abs(fn(value))>1e-5)throw Error('Possibile discontinuità: non confermo uno zero.');result='x ≈ '+value.toPrecision(10)+' · bisezione numerica.';}
 $('calculusResult').textContent=result;
 }catch(e){$('calculusResult').textContent=e.message;}};
for(const [id,action]of [['calculateValue','value'],['calculateDerivative','derivative'],['calculateIntegral','integral'],['calculateRoot','root']])$(id).addEventListener('click',()=>calculus(action));
const formulas=[['Derivata','\\frac{d}{dx}f(x)'],['Matrice','\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}'],['Sistema','\\begin{cases}x+y=1\\\\x-y=0\\end{cases}'],['Fourier','X(f)=\\int_{-\\infty}^{+\\infty}x(t)e^{-j2\\pi ft}dt'],['Logaritmo','\\log_a x=\\frac{\\ln x}{\\ln a}'],['Binomio','\\binom{n}{k}=\\frac{n!}{k!(n-k)!}']];for(const [title,value]of formulas)document.querySelector('.formula-snippets').appendChild(button(title,()=>{setFormula(value);}));
