insert('drawingExamples','<h4>Segnali e armoniche di Fourier</h4><div class="fourier-settings"><label>Segnale<select id="fourierWave"><option value="square">Onda quadra</option><option value="triangle">Onda triangolare</option><option value="saw">Dente di sega</option></select></label><label>Armoniche<input id="fourierTerms" type="range" min="1" max="15" value="5"><output id="fourierTermsValue">5</output></label><label><input id="fourierHarmonics" type="checkbox" checked> Mostra singole armoniche</label></div><div class="tool-actions"><button id="drawFourier" class="secondary-button" type="button">Disegna Fourier</button><button id="drawSine" class="secondary-button" type="button">Sinusoide</button><button id="drawUnitCircle" class="secondary-button" type="button">Cerchio goniometrico</button></div><p class="tool-note">Gli esempi si aggiungono al disegno e si possono annullare. Asse orizzontale: −π … π. Asse verticale: ampiezza. La somma arancione approssima il segnale verde.</p>');
