function drawingExample(kind){if(!doc)return;const lines=[],add=(points,color='#819087',size=2,tool='pen',dash=false)=>lines.push({points,color,size,tool,dash});
 add([[90,320],[920,320]],'#819087',2,'arrow');add([[120,570],[120,80]],'#819087',2,'arrow');
 if(kind==='unit'){add([[360,150],[700,490]],'#789476',2,'ellipse');add([[530,320],[677,235]],'#d38651',3,'arrow');add([[677,235],[677,320]],'#789476',2,'line',true);add([[530,320],[677,320]],'#347c9d',3,'line');}
 else{const terms=kind==='sine'?1:Number($('fourierTerms').value),wave=$('fourierWave').value,xs=Array.from({length:801},(_,i)=>-Math.PI+i*Math.PI*2/800),points=f=>xs.map((x,i)=>[120+i,320-140*f(x)]),harmonic=n=>{const k=wave==='saw'?n:2*n-1;return x=>wave==='triangle'?8/(Math.PI*Math.PI)*(-1)**(n-1)*Math.sin(k*x)/(k*k):wave==='saw'?2/Math.PI*(-1)**(n+1)*Math.sin(k*x)/k:4/Math.PI*Math.sin(k*x)/k;};
 if(kind==='sine')add(points(Math.sin),'#347c9d',3);else{add(points(x=>wave==='square'?Math.sign(Math.sin(x)):wave==='triangle'?2/Math.PI*Math.asin(Math.sin(x)):x/Math.PI),'#789476',2,'pen',true);if($('fourierHarmonics').checked){const colors=['#347c9d','#8772ad','#d36776','#8f753c','#5a9672'];for(let n=1;n<=terms;n++)add(points(harmonic(n)),colors[(n-1)%colors.length],1);}add(points(x=>Array.from({length:terms},(_,i)=>harmonic(i+1)(x)).reduce((a,b)=>a+b,0)),'#d38651',3);}}
 const strokes=doc.content.drawing.strokes;if(strokes.length+lines.length>500||strokes.reduce((n,s)=>n+s.points.length,0)+lines.reduce((n,s)=>n+s.points.length,0)>50000){$('drawingMessage').textContent='Il disegno è pieno. Crea una nuova pagina per aggiungere l’esempio.';return;}drawingHistory.push(clone(strokes));drawingHistory=drawingHistory.slice(-20);strokes.push(...lines);redrawDrawing();changed();$('drawingMessage').textContent=kind==='fourier'?'Fourier: '+$('fourierTerms').value+' armoniche · verde: segnale · arancione: somma.':kind==='sine'?'Sinusoide inserita.':'Cerchio goniometrico inserito.';
}
