const oscilloscope=createOscilloscope();
// Selection redraws SVG nodes on pointerup, so native dblclick is not reliable.
// Track completed, stationary taps by component id across those redraws.
let instrumentPress=null,instrumentTap=null;
function activateInstrument(part){if(part.type==='scope')oscilloscope.select(part.id);else if(part.type==='switch')toggleSwitches([part]);}
document.addEventListener('pointerdown',event=>{
 instrumentPress=null;if(event.button>0||!doc||!$('circuitSvg').contains(event.target)||event.target.closest('[data-port]')){instrumentTap=null;return;}
 const group=event.target.closest('[data-component-id]'),part=doc.content.circuit.components.find(p=>p.id===group?.dataset.componentId);
 if(!part||!['scope','switch'].includes(part.type)||wireStart||circuitPan||circuitSpaceHeld){instrumentTap=null;return;}
 instrumentPress={id:part.id,note:doc.id,pointer:event.pointerId,x:event.clientX,y:event.clientY,moved:false};
},true);
document.addEventListener('pointermove',event=>{if(instrumentPress&&event.pointerId===instrumentPress.pointer&&Math.hypot(event.clientX-instrumentPress.x,event.clientY-instrumentPress.y)>4)instrumentPress.moved=true;},true);
document.addEventListener('pointerup',event=>{
 const press=instrumentPress;instrumentPress=null;if(!press||press.pointer!==event.pointerId||press.moved||press.note!==doc?.id){instrumentTap=null;return;}
 const now=performance.now(),part=doc.content.circuit.components.find(p=>p.id===press.id);
 if(part&&instrumentTap?.id===press.id&&instrumentTap.note===press.note&&now-instrumentTap.time<420&&Math.hypot(press.x-instrumentTap.x,press.y-instrumentTap.y)<8){instrumentTap=null;activateInstrument(part);}
 else instrumentTap={...press,time:now};
},true);
document.addEventListener('pointercancel',()=>{instrumentPress=instrumentTap=null;},true);

function resetSimulationForNote(force=false){
 if(!force&&simulationNoteId===doc?.id)return;simulationGeneration++;const previous=job;job=null;clearTimeout(pollTimer);if(previous)api('/api/tramonto/simulations/'+previous+'/cancel','POST',{}).catch(()=>{});simulationNoteId=null;lastSimulation=null;oscilloscope.reset();$('simulationResult').replaceChildren();$('simulationStatus').textContent='';$('stopSimulation').disabled=true;$('downloadSpiceCsv').disabled=true;$('simulateCircuit').disabled=!spiceAvailable;
}
async function poll(){
 const id=job,generation=simulationGeneration,noteId=simulationNoteId;if(!id)return;
 try{const response=await api('/api/tramonto/simulations/'+id);if(generation!==simulationGeneration||id!==job||doc?.id!==noteId)return;
  if(!response.done){pollTimer=setTimeout(poll,350);return;}job=null;$('simulateCircuit').disabled=!spiceAvailable;$('stopSimulation').disabled=true;
  if(response.result&&!response.result.error){lastSimulation=response.result;renderSimulation(response.result);$('simulationStatus').textContent='Simulazione completata · '+response.result.engine;$('downloadSpiceCsv').disabled=false;}
  else{const message=response.result?.error||'Simulazione interrotta.';$('simulationStatus').textContent=message;oscilloscope.fail(message);}
 }catch(e){if(generation!==simulationGeneration)return;job=null;$('simulateCircuit').disabled=!spiceAvailable;$('stopSimulation').disabled=true;$('simulationStatus').textContent=e.message;oscilloscope.fail(e.message);}
}
$('simulateCircuit').addEventListener('click',async()=>{
 const current=doc;if(!current)return;
 const generation=++simulationGeneration;simulationNoteId=current.id;oscilloscope.acquire();lastSimulation=null;$('downloadSpiceCsv').disabled=true;$('simulateCircuit').disabled=true;$('simulationStatus').textContent='Preparazione dell’acquisizione…';
 try{if(!await saveDoc()){oscilloscope.fail('Salva le modifiche prima di avviare la simulazione.');$('simulateCircuit').disabled=!spiceAvailable;return;}if(current!==doc||generation!==simulationGeneration)return;
  const response=await api('/api/tramonto/simulations','POST',{note_id:current.id,options:spiceOptions()});
  if(current!==doc||generation!==simulationGeneration){api('/api/tramonto/simulations/'+response.job_id+'/cancel','POST',{}).catch(()=>{});return;}
  job=response.job_id;$('stopSimulation').disabled=false;$('simulationStatus').textContent='Simulazione in corso…';poll();
 }catch(e){if(generation!==simulationGeneration)return;$('simulateCircuit').disabled=!spiceAvailable;$('simulationStatus').textContent=e.message;oscilloscope.fail(e.message);}
});
