function ipNumber(s){if(typeof s!=='string'||!/^\d{1,3}(\.\d{1,3}){3}$/.test(s)||s.split('.').some(n=>Number(n)>255))throw Error('IPv4 non valido.');return s.split('.').reduce((v,n)=>v*256+Number(n),0)>>>0;}
