function cidr(s){const [ip,prefix]=s.split('/');if(prefix===undefined||!/^\d{1,2}$/.test(prefix)||Number(prefix)>32)throw Error('Usa IPv4/prefisso, ad esempio 192.168.1.2/24.');const n=ipNumber(ip),p=Number(prefix),mask=p===0?0:(0xffffffff<<(32-p))>>>0,start=(n&mask)>>>0,size=2**(32-p);return{ip:n,prefix:p,mask,start,end:start+size-1,size};}
function trace(sourceId,targetId){const net=network(),source=net.nodes.find(n=>n.id===sourceId),target=net.nodes.find(n=>n.id===targetId);if(!source||!target||source.id===target.id)throw Error('Scegli due dispositivi diversi.');if(!source.enabled||!target.enabled)throw Error('Un dispositivo è disattivato.');const a=cidr(source.ip),b=cidr(target.ip),same=(a.ip&b.mask)===(b.ip&b.mask)&&(a.ip&a.mask)===(b.ip&a.mask),routes=[];
const queue=[[source.id]],seen=new Set();while(queue.length){const path=queue.shift(),id=path.at(-1);if(seen.has(id))continue;seen.add(id);if(id===target.id){routes.push(path);break;}const current=net.nodes.find(n=>n.id===id);if(id!==source.id&&!['switch','router','accesspoint','firewall','cloud'].includes(current.type))continue;for(const link of net.links.filter(l=>l.enabled&&(l.from===id||l.to===id))){const other=link.from===id?link.to:link.from,n=net.nodes.find(v=>v.id===other);if(n?.enabled&&!path.includes(other)&&(current.type==='router'||n.type==='router'||current.vlan===n.vlan))queue.push([...path,other]);}}
if(!routes.length)throw Error('Nessun percorso attivo: verifica cavi, VLAN e dispositivi.');const path=routes[0],routers=path.map(id=>net.nodes.find(n=>n.id===id)).filter(n=>n.type==='router');if(!same){if(routers.length!==1)throw Error('Tra sottoreti diverse serve un solo router con due interfacce. Il routing tra più router richiede configurazione non supportata.');const router=routers[0],interfaces=[router.ip,...router.interfaces].filter(Boolean).map(cidr),ga=ipNumber(source.gateway),gb=ipNumber(target.gateway);if(!interfaces.some(i=>i.ip===ga&&(a.ip&i.mask)===i.start)||!interfaces.some(i=>i.ip===gb&&(b.ip&i.mask)===i.start))throw Error('Gateway o interfacce router non corrispondono alle due sottoreti.');}else if(source.vlan!==target.vlan)throw Error('VLAN diverse: usa sottoreti e router distinti.');return path;}
function ping(){try{const path=trace($('pingSource').value,$('pingTarget').value),net=network();$('networkResult').textContent='ICMP simulato: risposta ricevuta · '+path.map(id=>net.nodes.find(n=>n.id===id).name).join(' → ')+' · '+(path.length-1)+' collegamenti. Nessun tempo di rete reale misurato.';const svg=$('networkSvg'),packet=svgNode('circle',{r:8,fill:'#edab58',stroke:'#fff','stroke-width':2});svg.appendChild(packet);const coords=path.map(id=>net.nodes.find(n=>n.id===id)),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:1200,start=performance.now();function tick(now){if(!packet.isConnected)return;const fraction=duration?Math.max(0,Math.min(1,(now-start)/duration)):1,position=fraction*(coords.length-1),i=Math.min(coords.length-2,Math.floor(position)),local=position-i;packet.setAttribute('cx',coords[i].x+(coords[i+1].x-coords[i].x)*local);packet.setAttribute('cy',coords[i].y+(coords[i+1].y-coords[i].y)*local);if(fraction<1)requestAnimationFrame(tick);else setTimeout(()=>packet.remove(),400);}requestAnimationFrame(tick);}catch(e){$('networkResult').textContent=e.message;}}
