async function insertFile(file,width=450,options={}){if(!doc||uploading)return false;const current=doc,replacement=options.replace;const oldId=replacement?.getAttribute('src')?.match(/images\/(\d+)/)?.[1];if(replacement&&(!replacement.isConnected||!oldId))return false;if(file.size>8*1024*1024){error('Massimo 8 MB per immagine.');return false;}if(!replacement&&current.content.images.length>=30){error('Massimo trenta immagini per pagina.');return false;}if(!await saveDoc())return false;uploading=true;$('saveStatus').textContent='Salvataggio oggetto…';try{const headers={'Content-Type':file.type||'image/png','X-CSRF-Token':csrf,'X-Image-Name':encodeURIComponent((file.name||'Laboratorio.png').slice(0,180))};if(oldId)headers['X-Replace-Image']=oldId;const response=await fetch('/api/tramonto/notes/'+current.id+'/images',{method:'POST',credentials:'same-origin',headers,body:file}),data=await response.json();if(!response.ok)throw Error(data.error||'Immagine non valida.');if(!oldId)current.content.images.push(data.id);if(current!==doc)return false;
if(oldId){const stamp=Date.now();for(const image of $('richEditor').querySelectorAll('img')){if(image.getAttribute('src')?.match(/images\/(\d+)/)?.[1]!==oldId)continue;image.src='/api/tramonto/images/'+data.id+'?v='+stamp;image.dataset.latex=options.latex;image.alt='Formula matematica modificabile';}showText();selectImage(replacement);}
else{insertExisting(data.id,width);if(options.latex){selectedImage.dataset.latex=options.latex;selectedImage.alt='Formula matematica modificabile';}}
changed();renderImages();return true;
}catch(e){error(e.message);return false;}finally{uploading=false;if(current===doc)await saveDoc();}}
