let snapshotting=false;async function snapshot(id,options={}){if(!doc||snapshotting)return false;snapshotting=true;const current=doc;try{if(id==='plotSvg'&&!plot(true))throw Error('Correggi le funzioni o gli intervalli prima di inserirli.');const element=$(id);let blob,width=450;if(!(element instanceof HTMLCanvasElement)&&!(element instanceof SVGElement)){await document.fonts.ready;const host=node('div'),formula=(element.querySelector('.katex')||element).cloneNode(true);host.style.cssText='position:absolute;left:-10000px;top:0;width:max-content;padding:12px;background:#fffdf7;color:#263c31;font-size:20px';formula.style.display='inline-block';formula.style.width='max-content';formula.style.textAlign='left';host.appendChild(formula);document.body.appendChild(host);try{width=Math.min(450,Math.max(80,Math.ceil(host.getBoundingClientRect().width)));const canvas=await html2canvas(host,{backgroundColor:'#fffdf7',scale:2,logging:false});blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));}finally{host.remove();}}else if(element instanceof HTMLCanvasElement)blob=await new Promise(resolve=>element.toBlob(resolve,'image/png'));else{const svg=element.cloneNode(true);svg.setAttribute('xmlns',NS);const box=svg.viewBox.baseVal;svg.setAttribute('width',box.width);svg.setAttribute('height',box.height);const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const canvas=node('canvas');const scale=Math.min(1,2000/Math.max(box.width,box.height));canvas.width=Math.max(1,Math.round(box.width*scale));canvas.height=Math.max(1,Math.round(box.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fffdf7';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));}finally{URL.revokeObjectURL(url);}}if(!blob)throw Error('Immagine non generata.');if(doc!==current)throw Error('La pagina è cambiata durante l’inserimento. Seleziona la pagina desiderata e riprova.');return await insertFile(new File([blob],id+'.png',{type:'image/png'}),width,options);}catch(e){error(e.message);return false;}finally{snapshotting=false;}}
