// One selection gesture for both diagram editors. Selection stays out of saved data.
function diagramSelection(config){
 const svg=$(config.svg),selected=new Set();let gesture=null,hold=0,additive=false,box=null;
 const items=()=>config.items(),nodes=()=>items().filter(i=>!i.link),point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());};
 function sync(){const all=items().filter(i=>selected.has(i.key));config.select(all.length===1?all[0]:null);}
 function render(){
  const valid=new Set(items().map(i=>i.key));for(const key of selected)if(!valid.has(key))selected.delete(key);
  for(const element of svg.querySelectorAll(config.selector)){
   const key=config.key(element),active=selected.has(key);element.setAttribute('data-selected',String(active));
   if(active)config.highlight(element);
  }
  if(box){const rect=svgNode('rect',{x:box.x,y:box.y,width:box.width,height:box.height,fill:'#5482a020',stroke:'#5482a0','stroke-width':2,'stroke-dasharray':'6 4','pointer-events':'none',class:'selection-marquee'});svg.appendChild(rect);}
  $(config.status).textContent=selected.size?selected.size+' oggett'+(selected.size===1?'o selezionato':'i selezionati')+' · Canc/Delete per eliminare · Esc per deselezionare':'Maiusc + clic o pressione prolungata per selezionare più oggetti. Trascina sullo sfondo per selezionare un’area.';
 }
 const repaint=()=>{sync();if(config.svg==='circuitSvg'&&gesture?.moved)scheduleCircuitRender();else config.render();};
 function finish(){clearTimeout(hold);if(gesture?.moved)changed();gesture=null;box=null;repaint();}
 function clear(){clearTimeout(hold);gesture=null;box=null;additive=false;selected.clear();sync();render();}
 svg.addEventListener('contextmenu',e=>e.preventDefault());
 svg.addEventListener('pointerdown',e=>{
  if(!doc||e.button>0)return;
  if(config.svg==='circuitSvg'&&(wireStart||e.target.closest('[data-port]')||circuitMode==='place'&&placing==='switch'&&e.target.closest('[data-wire]')))return;
  const hit=e.target.closest(config.selector);if(config.mode()!=='select'){if(config.mode()!=='place'||!hit)return;config.activate();}
  e.preventDefault();e.stopImmediatePropagation();svg.focus({preventScroll:true});
  const element=e.target.closest(config.selector),key=element?config.key(element):null,p=point(e),previous=new Set(selected),withKey=e.shiftKey||e.ctrlKey||e.metaKey;
  if(key){if(withKey||additive){if(selected.has(key))selected.delete(key);else selected.add(key);}else if(!selected.has(key)){selected.clear();selected.add(key);}}
  else if(!withKey){selected.clear();additive=false;}
  gesture={pointer:e.pointerId,x:e.clientX,y:e.clientY,p,key,previous,withKey,origins:nodes().filter(i=>selected.has(i.key)).map(i=>({item:i,x:i.value.x,y:i.value.y})),marquee:!key&&e.pointerType!=='touch',touch:e.pointerType==='touch',moved:false};
  svg.setPointerCapture(e.pointerId);
  hold=setTimeout(()=>{if(!gesture)return;additive=true;if(key){selected.clear();for(const k of previous)selected.add(k);if(previous.has(key))selected.delete(key);else selected.add(key);gesture.origins=nodes().filter(i=>selected.has(i.key)).map(i=>({item:i,x:i.value.x,y:i.value.y}));}else gesture.marquee=true;repaint();},450);
  repaint();
 },true);
 svg.addEventListener('pointermove',e=>{
  if(!gesture||gesture.pointer!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const g=gesture,p=point(e),distance=Math.hypot(e.clientX-g.x,e.clientY-g.y);if(distance<6&&!g.moved)return;
  clearTimeout(hold);if(g.marquee){box={x:Math.min(g.p.x,p.x),y:Math.min(g.p.y,p.y),width:Math.abs(p.x-g.p.x),height:Math.abs(p.y-g.p.y)};selected.clear();if(g.withKey||additive)for(const key of g.previous)selected.add(key);for(const i of nodes())if(i.value.x>=box.x&&i.value.x<=box.x+box.width&&i.value.y>=box.y&&i.value.y<=box.y+box.height)selected.add(i.key);repaint();return;}
  if(!g.key||!g.origins.length)return;if(!g.moved){config.history();if(config.svg==='circuitSvg')g.wireOrigins=captureCircuitWireMove(g.origins.map(o=>o.item.value.id));g.moved=true;}
  let dx=Math.round((p.x-g.p.x)/10)*10,dy=Math.round((p.y-g.p.y)/10)*10;
  dx=Math.max(Math.max(...g.origins.map(o=>40-o.x)),Math.min(Math.min(...g.origins.map(o=>(config.svg==='circuitSvg'?CIRCUIT_LIMIT-60:960)-o.x)),dx));
  dy=Math.max(Math.max(...g.origins.map(o=>40-o.y)),Math.min(Math.min(...g.origins.map(o=>(config.svg==='circuitSvg'?CIRCUIT_LIMIT-60:600)-o.y)),dy));
  for(const o of g.origins){o.item.value.x=o.x+dx;o.item.value.y=o.y+dy;}if(config.svg==='circuitSvg'){moveCircuitWireCorners(g.wireOrigins,dx,dy);growCircuitCanvas();circuitEdgePan(e);}repaint();
 },true);
 for(const event of ['pointerup','pointercancel','lostpointercapture'])svg.addEventListener(event,e=>{if(!gesture)return;e.stopImmediatePropagation();finish();},true);
 function remove(){if(!doc||!selected.size)return false;config.history();config.remove(items().filter(i=>selected.has(i.key)));clear();config.render();changed();return true;}
 function rotate(){const parts=nodes().filter(i=>selected.has(i.key));if(!parts.length||!config.rotate)return false;config.history();parts.forEach(i=>config.rotate(i.value));repaint();changed();return true;}
 svg.addEventListener('keydown',e=>{if(['Delete','Backspace'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();remove();}else if(e.key==='Escape'){e.preventDefault();clear();config.render();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();items().forEach(i=>selected.add(i.key));repaint();}},true);
 for(const id of config.reset)$(id).addEventListener('click',clear,true);
 return {render,clear,remove,rotate,items:()=>items().filter(i=>selected.has(i.key)),select:keys=>{selected.clear();keys.forEach(k=>selected.add(k));repaint();}};
}
for(const [pane,status]of [['pane-network','networkSelectionStatus'],['pane-circuit','circuitSelectionStatus']]){const hint=node('p');hint.id=status;hint.className='tool-note';hint.setAttribute('role','status');$(pane).querySelector(pane==='pane-circuit'?'#circuitSvg':'#networkSvg').before(hint);}
networkSelection=diagramSelection({svg:'networkSvg',status:'networkSelectionStatus',selector:'[data-net-id],[data-link-id]',mode:()=>netMode,activate:()=>{netMode='select';netStart=null;},
 key:e=>e.hasAttribute('data-net-id')?'n:'+e.dataset.netId:'l:'+e.dataset.linkId,
 items:()=>[...network().nodes.map(n=>({key:'n:'+n.id,value:n})),...network().links.map(l=>({key:'l:'+l.id,value:l,link:true}))],
 select:i=>{netSelected=i?.value.id||null;},history:netSnapshot,render:renderNetwork,
 highlight:e=>{const shape=e.matches('[data-net-id]')?e.firstElementChild:e;shape.setAttribute('stroke','#dd8b50');shape.setAttribute('stroke-width',5);},
 remove:all=>{const net=network(),ids=new Set(all.filter(i=>!i.link).map(i=>i.value.id));net.nodes=net.nodes.filter(n=>!ids.has(n.id));net.links=net.links.filter(l=>!all.some(i=>i.link&&i.value===l)&&!ids.has(l.from)&&!ids.has(l.to));},
 reset:['networkUndo','networkExample','networkWire','networkSelect']});
circuitSelection=diagramSelection({svg:'circuitSvg',status:'circuitSelectionStatus',selector:'[data-component-id],[data-wire]',mode:()=>circuitMode,activate:()=>{circuitMode='select';placing=null;wireStart=null;},
 key:e=>e.hasAttribute('data-component-id')?'c:'+e.dataset.componentId:'w:'+e.dataset.wire,
 items:()=>doc?[...doc.content.circuit.components.map(p=>({key:'c:'+p.id,value:p})),...doc.content.circuit.wires.map(w=>({key:'w:'+w.id,value:w,link:true}))]:[],
 select:i=>{selectedPart=i&&!i.link?i.value.id:null;selectedWire=i?.link?i.value.id:null;},history:historyCircuit,render:renderCircuit,
 highlight:e=>{if(e.hasAttribute('data-component-id')){const shape=e.firstElementChild;shape.setAttribute('stroke','#d38651');shape.setAttribute('stroke-width',3);shape.setAttribute('fill','#f8d9aa55');}else if(e.getAttribute('stroke')!=='transparent'){e.setAttribute('stroke-width',5);}},
 remove:all=>{const c=doc.content.circuit,ids=new Set(all.filter(i=>!i.link).map(i=>i.value.id));c.components=c.components.filter(p=>!ids.has(p.id));c.wires=c.wires.filter(w=>!all.some(i=>i.link&&i.value===w)&&!ids.has(w.from.component)&&!ids.has(w.to.component));},rotate:p=>{p.rotation=(p.rotation+90)%360;},
 reset:['undoCircuit','selectCircuit','wireCircuit']});
window.TramontoLab.circuitSelection=circuitSelection;
$('circuitExample').addEventListener('change',()=>{circuitSelection.clear();renderCircuit();});

// Derived teaching tools use the same saved topology; they never send packets.
const networkActions=$('networkPing').parentElement;
networkActions.append(button('Traceroute simulato',()=>showTrace()),button('Controlla topologia',()=>diagnose()));
const editActions=$('networkSelect').parentElement;
editActions.append(button('Duplica selezione',duplicateNetwork),button('Disponi a griglia',arrangeNetwork));
const report=node('pre');report.id='networkReport';report.className='network-console';report.setAttribute('role','status');$('networkResult').after(report);
networkActions.append(button('Inserisci rapporto nel quaderno',()=>{if(!report.textContent){diagnose();}insertReport(report.textContent,'Verifica della rete');}));
function showTrace(){try{const path=trace($('pingSource').value,$('pingTarget').value),net=network();report.textContent='TRACEROUTE DIDATTICO · percorso nella topologia\n'+path.map((id,i)=>{const n=net.nodes.find(v=>v.id===id);return(i+1)+'. '+n.name+' · '+netKinds[n.type]+' · '+(n.ip||'nessun indirizzo');}).join('\n')+'\nNessun pacchetto reale inviato; switch e access point sono mostrati come collegamenti, non come hop IP.';}catch(e){report.textContent=e.message;}}
function diagnose(){
 const net=network(),issues=[],seen=new Map(),endpoints=['pc','laptop','server','printer'];
 for(const n of net.nodes){
  if(!n.enabled){issues.push(n.name+': dispositivo disattivato.');continue;}
  if(!net.links.some(l=>l.enabled&&(l.from===n.id||l.to===n.id)))issues.push(n.name+': nessun collegamento attivo.');
  if(endpoints.includes(n.type)&&!n.ip)issues.push(n.name+': manca IPv4/prefisso.');
  try{for(const value of [n.ip,...n.interfaces].filter(Boolean)){const c=cidr(value),key=n.vlan+':'+c.ip;if(seen.has(key)&&seen.get(key)!==n.id)issues.push(n.name+': indirizzo duplicato '+ipText(c.ip)+' in VLAN '+n.vlan+'.');seen.set(key,n.id);if(c.prefix<31&&(c.ip===c.start||c.ip===c.end))issues.push(n.name+': indirizzo di rete/broadcast assegnato al dispositivo.');}
   if(n.gateway&&endpoints.includes(n.type)&&n.ip){const c=cidr(n.ip),g=ipNumber(n.gateway);if((g&c.mask)>>>0!==c.start)issues.push(n.name+': gateway fuori dalla sottorete.');else if(!net.nodes.some(r=>r.type==='router'&&r.enabled&&[r.ip,...r.interfaces].some(v=>v&&cidr(v).ip===g)))issues.push(n.name+': gateway assente o router disattivato.');}
  }catch(e){issues.push(n.name+': '+e.message);}
 }
 const inactive=net.links.filter(l=>!l.enabled).length;if(inactive)issues.push(inactive+' collegamenti disattivati.');
 report.textContent='DIAGNOSTICA DIDATTICA · '+net.nodes.length+' dispositivi, '+net.links.length+' collegamenti\n'+(!net.nodes.length?'Aggiungi dispositivi o carica un esempio.':issues.length?issues.map((s,i)=>(i+1)+'. '+s).join('\n'):'Nessun problema rilevato nei controlli su indirizzi, gateway e collegamenti. Usa Ping per verificare un percorso.');return report.textContent;
}
function duplicateNetwork(){if(!doc)return;const net=network(),all=networkSelection.items(),chosen=all.filter(i=>!i.link);if(!chosen.length){$('networkResult').textContent='Seleziona uno o più dispositivi da duplicare.';return;}const ids=new Map(chosen.map(i=>[i.value.id,crypto.randomUUID()])),links=net.links.filter(l=>ids.has(l.from)&&ids.has(l.to));if(net.nodes.length+chosen.length>80||net.links.length+links.length>160){$('networkResult').textContent='Limite: 80 dispositivi e 160 collegamenti.';return;}netSnapshot();const copies=chosen.map(i=>({...clone(i.value),id:ids.get(i.value.id),name:(i.value.name+' copia').slice(0,60),x:Math.min(960,i.value.x+40),y:Math.min(600,i.value.y+40),ip:'',gateway:'',interfaces:[]}));net.nodes.push(...copies);net.links.push(...links.map(l=>({...clone(l),id:crypto.randomUUID(),from:ids.get(l.from),to:ids.get(l.to)})));networkSelection.select(copies.map(n=>'n:'+n.id));changed();}
function arrangeNetwork(){if(!doc||!network().nodes.length)return;netSnapshot();const net=network(),columns=Math.ceil(Math.sqrt(net.nodes.length*1.5)),rows=Math.ceil(net.nodes.length/columns);net.nodes.forEach((n,i)=>{n.x=Math.round((80+(i%columns)*840/Math.max(1,columns-1))/10)*10;n.y=Math.round((80+Math.floor(i/columns)*480/Math.max(1,rows-1))/10)*10;});renderNetwork();changed();}
function insertReport(text,title){if(!doc||!text)return;const content=node('div'),heading=node('h3',title),body=node('pre',text);content.append(heading,body,node('p'));document.querySelector('[data-pane=text]').click();restoreCaret();document.execCommand('insertHTML',false,cleanHtml(content.innerHTML));changed();schedulePages();}
insert('pane-network','<section class="math-section"><h3>Progetta le sottoreti.</h3><p class="tool-note">Dividi una rete in parti uguali o assegna blocchi VLSM in base agli host richiesti. I risultati sono calcoli locali IPv4.</p><div class="tool-actions"><label>Rete di partenza<input id="subnetBase" value="192.168.10.0/24"></label><label>Nuovo prefisso<input id="subnetPrefix" type="number" min="1" max="32" value="26"></label><button id="subnetSplit" class="secondary-button">Dividi rete</button></div><div class="tool-actions"><label>Host per sottorete<input id="vlsmHosts" value="50, 20, 10" placeholder="50, 20, 10"></label><button id="vlsmCalculate" class="secondary-button">Calcola VLSM</button><button id="subnetInsert" class="secondary-button">Inserisci tabella nel quaderno</button></div><p id="subnetPlanMessage" class="tool-message" role="status"></p><div class="subnet-plan"><table id="subnetPlan" class="lab-table"></table></div></section>');
let subnetPlan=[];
function showPlan(rows){subnetPlan=rows;const table=$('subnetPlan');table.replaceChildren();const tr=node('tr');for(const text of ['Rete','Primo host','Ultimo host','Broadcast','Host'])tr.appendChild(node('th',text));table.appendChild(tr);for(const c of rows){const row=node('tr');for(const text of [ipText(c.start)+'/'+c.prefix,ipText(c.prefix>=31?c.start:c.start+1),ipText(c.prefix>=31?c.end:c.end-1),c.prefix>=31?'—':ipText(c.end),String(c.prefix>=31?c.size:c.size-2)])row.appendChild(node('td',text));table.appendChild(row);}$('subnetPlanMessage').textContent=rows.length+' sottoreti calcolate.';}
function planError(e){subnetPlan=[];$('subnetPlan').replaceChildren();$('subnetPlanMessage').textContent=e.message;}
$('subnetSplit').addEventListener('click',()=>{try{const base=cidr($('subnetBase').value.trim()),prefix=Number($('subnetPrefix').value);if(!Number.isInteger(prefix)||prefix<=base.prefix||prefix>32)throw Error('Il nuovo prefisso deve essere maggiore di quello della rete e al massimo 32.');const count=2**(prefix-base.prefix);if(count>64)throw Error('Mostra al massimo 64 sottoreti: scegli un prefisso più vicino a quello iniziale.');const size=2**(32-prefix);showPlan(Array.from({length:count},(_,i)=>cidr(ipText(base.start+i*size)+'/'+prefix)));}catch(e){planError(e);}});
$('vlsmCalculate').addEventListener('click',()=>{try{const base=cidr($('subnetBase').value.trim()),raw=$('vlsmHosts').value.split(/[,;\s]+/).filter(Boolean);if(!raw.length||raw.length>32||raw.some(s=>!/^\d+$/.test(s)))throw Error('Inserisci da 1 a 32 richieste di host interi, separate da virgole.');const hosts=raw.map(Number);if(hosts.some(n=>n<1||n>2**30-2))throw Error('Numero di host fuori intervallo.');const sizes=hosts.map(n=>2**Math.ceil(Math.log2(n+2))).sort((a,b)=>b-a),rows=[];let next=base.start;for(const size of sizes){next=Math.ceil(next/size)*size;if(next+size-1>base.end)throw Error('Gli host richiesti non entrano nella rete di partenza.');rows.push(cidr(ipText(next)+'/'+(32-Math.log2(size))));next+=size;}showPlan(rows);}catch(e){planError(e);}});
$('subnetInsert').addEventListener('click',()=>{if(!subnetPlan.length){$('subnetPlanMessage').textContent='Calcola prima una suddivisione.';return;}restoreCaret();document.querySelector('[data-pane=text]').click();document.execCommand('insertHTML',false,cleanHtml('<h3>Piano delle sottoreti</h3>'+$('subnetPlan').outerHTML+'<p><br></p>'));changed();schedulePages();});
const originalSubnet=$('subnetCalculate');originalSubnet.addEventListener('click',()=>{try{const c=cidr($('subnetInput').value.trim()),first=c.prefix>=31?c.start:c.start+1,last=c.prefix>=31?c.end:c.end-1;$('subnetResult').textContent+=' · primo '+ipText(first)+' · ultimo '+ipText(last)+' · wildcard '+ipText((~c.mask)>>>0);}catch(_){}});
const cli=$('networkCli');cli.addEventListener('submit',e=>{const command=$('networkCommand').value.trim().toLowerCase();if(command==='diagnose'||command==='check topology'){e.preventDefault();e.stopImmediatePropagation();$('networkConsole').textContent=diagnose();}else if(command.startsWith('traceroute ')||command.startsWith('tracert ')){e.preventDefault();e.stopImmediatePropagation();const ip=command.split(/\s+/)[1],target=network().nodes.find(n=>n.ip.split('/')[0]===ip);if(!target){$('networkConsole').textContent='Destinazione assente nella topologia.';return;}$('pingTarget').value=target.id;showTrace();$('networkConsole').textContent=report.textContent;}else if(command==='show ip route'){e.preventDefault();e.stopImmediatePropagation();$('networkConsole').textContent=network().nodes.filter(n=>n.type==='router').map(n=>n.name+'\n'+[n.ip,...n.interfaces].filter(Boolean).map(v=>{const c=cidr(v);return'C '+ipText(c.start)+'/'+c.prefix+' direttamente connessa · '+ipText(c.ip);}).join('\n')).join('\n\n')||'Nessun router configurato. Mostra solo reti direttamente connesse.';}},true);
window.TramontoLab.networkSelection=networkSelection;
