for(const [id,name]of [['networkSelect','mouse-pointer-2'],['selectCircuit','mouse-pointer-2'],['networkWire','cable'],['wireCircuit','cable'],['networkDelete','trash'],['deleteCircuitPart','trash'],['networkUndo','undo-2'],['undoCircuit','undo-2'],['exportNetwork','image']]){const glyph=icon(name);if(glyph)$(id).prepend(glyph);}
for(const [label,name]of [['Traceroute simulato','route'],['Controlla topologia','scan-search'],['Duplica selezione','copy'],['Disponi a griglia','layout-grid']]){const item=Array.from($('pane-network').querySelectorAll('button')).find(b=>b.textContent===label),glyph=icon(name);if(item&&glyph)item.prepend(glyph);}

// Palettes have their own scroll area beside the work, keeping the sheet stationary.
function configureToolDock(host,panel,label){
 panel.classList.add('tool-dock');panel.id=host.id+'Tools';panel.setAttribute('aria-label',label);
 const header=node('div');header.className='tool-dock-header';const close=button('✕',()=>setOpen(false));close.title='Chiudi pannello strumenti';close.setAttribute('aria-label','Chiudi '+label);header.append(node('strong',label),close);panel.prepend(header);
 const toggle=button(label,()=>setOpen(!panel.classList.contains('dock-open')));toggle.className='secondary-button tool-dock-toggle';toggle.prepend(toolIcon('layout-grid'));toggle.setAttribute('aria-controls',panel.id);toggle.setAttribute('aria-expanded','false');host.prepend(toggle);
 function setOpen(open){panel.classList.toggle('dock-open',open);toggle.setAttribute('aria-expanded',String(open));if(open)close.focus({preventScroll:true});else toggle.focus({preventScroll:true});}
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();setOpen(false);}});
 panel.addEventListener('click',e=>{if(matchMedia('(max-width:1200px)').matches&&e.target.closest('[data-component],[data-draw-tool],#networkPalette button'))setOpen(false);});
 document.querySelectorAll('[data-pane]').forEach(b=>b.addEventListener('click',()=>{panel.classList.remove('dock-open');toggle.setAttribute('aria-expanded','false');}));
}
