insert('pane-circuit','<section class="circuit-import-panel"><h4>Importa Multisim</h4><button id="importCircuit" class="secondary-button" type="button">Importa Multisim / SPICE</button><input id="circuitImportFile" type="file" accept=".ms10,.ms11,.ms12,.ms13,.ms14,.ms15,.ms16,.ms17,.ms18,.ms19,.ewprj,.xml,.cir,.sp,.spi,.net,.spice" hidden><p class="tool-note">File Multisim nativi e netlist .cir: conversione in componenti e cavi modificabili. Massimo 8 MB. I componenti non supportati vengono segnalati senza modificare il progetto.</p><p id="circuitImportStatus" class="tool-message" role="status" aria-live="polite"></p><div id="circuitImportPreview" hidden><strong id="circuitImportSummary"></strong><ul id="circuitImportWarnings"></ul><div class="tool-actions"><button id="applyCircuitImport" class="primary-button" type="button">Usa lo schema convertito</button><button id="cancelCircuitImport" class="secondary-button" type="button">Annulla importazione</button></div><p class="tool-note">Il testo e i disegni della pagina restano salvati. «Annulla» nello schema ripristina il circuito precedente.</p></div></section>');
$('importCircuit').prepend(toolIcon('download'));let pendingImport=null,importGeneration=0;
function clearCircuitImport(){pendingImport=null;importGeneration++;$('circuitImportPreview').hidden=true;$('circuitImportStatus').textContent='';$('importCircuit').disabled=false;}
$('importCircuit').addEventListener('click',()=>$('circuitImportFile').click());
$('cancelCircuitImport').addEventListener('click',clearCircuitImport);
$('circuitImportFile').addEventListener('change',async event=>{
 const file=event.target.files[0],current=doc,generation=++importGeneration;event.target.value='';if(!file||!current)return;pendingImport=null;$('circuitImportPreview').hidden=true;$('importCircuit').disabled=true;$('circuitImportStatus').textContent='Conversione di '+file.name+'…';
 try{
  if(!file.size||file.size>8*1024*1024)throw Error('Scegli un file non vuoto, fino a 8 MB.');
  const response=await fetch('/api/tramonto/circuit/import',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf,'Content-Type':'application/octet-stream','X-Circuit-Name':encodeURIComponent(file.name.slice(0,180))},body:file}),result=await response.json();if(current!==doc||generation!==importGeneration)return;if(!response.ok)throw Error(result.error||'Conversione non riuscita.');
  pendingImport={result,current};$('circuitImportSummary').textContent=result.format+' · '+result.components+' oggetti · '+result.wires+' cavi';$('circuitImportWarnings').replaceChildren(...result.warnings.map(message=>node('li',message)));$('circuitImportPreview').hidden=false;$('applyCircuitImport').textContent=current.content.circuit.components.length?'Sostituisci schema · annullabile':'Usa lo schema convertito';$('circuitImportStatus').textContent='Conversione pronta: '+file.name+'. Controlla le eventuali differenze prima di applicare.';
 }catch(e){if(current===doc&&generation===importGeneration)$('circuitImportStatus').textContent=e.message;}finally{if(generation===importGeneration)$('importCircuit').disabled=false;}
});
$('applyCircuitImport').addEventListener('click',()=>{
 if(!pendingImport||pendingImport.current!==doc)return;const result=pendingImport.result;historyCircuit();cancelWire();circuitSelection?.clear();selectedPart=selectedWire=null;doc.content.circuit=clone(result.circuit);resetSimulationForNote(true);$('spiceAnalysis').value=doc.content.circuit.components.some(p=>['ac','function','scope'].includes(p.type))?'tran':'op';renderCircuit();fitCircuit();changed();clearCircuitImport();$('circuitMessage').textContent='Schema importato: '+result.components+' oggetti e '+result.wires+' collegamenti. Usa «Annulla» per ripristinare il precedente.';
});

function dockPane(id,label,elements){const host=$(id),layout=node('div'),stage=node('div'),panel=node('aside');layout.className='tool-deck';stage.className='tool-stage';for(const element of elements.filter(Boolean))panel.appendChild(element);stage.append(...host.childNodes);layout.append(stage,panel);host.appendChild(layout);configureToolDock(host,panel,label);}
